    <style>
        :root{--bg:#07111f;--panel:#0e1d31;--panel-2:#132640;--line:#29405f;--text:#f8fafc;--muted:#b7c4d6;--green:#4ade80;--red:#f87171;--focus:#7dd3fc;--paper:#f8fafc;--ink:#172033}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 80% 0,#123b35 0,transparent 30%),var(--bg);color:var(--text);font:16px/1.6 Inter,Arial,sans-serif}button,textarea{font:inherit}button{cursor:pointer}a{color:inherit}.skip-link{position:fixed;top:8px;left:8px;z-index:100;padding:10px 14px;border-radius:8px;background:#fff;color:#111827;font-weight:900;transform:translateY(-150%)}.skip-link:focus{transform:translateY(0)}.playground-shell{min-height:100vh}.lab-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px max(20px,calc((100vw - 1320px)/2));border-bottom:1px solid var(--line);background:rgba(7,17,31,.9);backdrop-filter:blur(14px);position:sticky;top:0;z-index:20}.lab-brand{font-weight:900;text-decoration:none}.lab-brand span{color:var(--green)}.lab-nav{display:flex;gap:10px;align-items:center}.lab-nav a{min-height:44px;display:inline-flex;align-items:center;padding:8px 14px;border-radius:10px;color:var(--muted);text-decoration:none;font-weight:800}.lab-nav a:hover,.lab-nav a:focus-visible{background:var(--panel-2);color:#fff}.lab-main{width:min(1320px,calc(100% - 40px));margin:0 auto;padding:38px 0 64px}.lab-intro{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:30px;align-items:end;margin-bottom:28px}.eyebrow{color:var(--green);font-size:13px;font-weight:900;letter-spacing:.1em;text-transform:uppercase}.lab-intro h1{font-size:clamp(34px,5vw,58px);line-height:1.05;margin:8px 0 12px}.lab-intro p{max-width:720px;color:var(--muted);font-size:18px;margin:0}.study-flow{display:flex;gap:8px;flex-wrap:wrap;justify-content:flex-end}.study-flow span{padding:7px 11px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:13px;font-weight:800}.study-progress{margin-bottom:24px;padding:16px 18px;border:1px solid var(--line);border-radius:14px;background:rgba(14,29,49,.8)}.progress-row{display:flex;justify-content:space-between;gap:12px;font-weight:800}.progress-track{height:8px;margin-top:10px;border-radius:99px;background:#20344f;overflow:hidden}.progress-track span{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--green),#22d3ee);transition:width .25s ease}.lab-grid{display:grid;grid-template-columns:280px minmax(0,1fr);gap:20px;align-items:start}.study-list{position:sticky;top:94px;display:grid;gap:8px;max-height:calc(100vh - 120px);overflow:auto;padding-right:4px}.study-button{width:100%;min-height:68px;padding:12px 14px;border:1px solid var(--line);border-radius:12px;background:var(--panel);color:var(--text);text-align:left;transition:background .2s,border-color .2s}.study-button:hover{background:var(--panel-2);border-color:#47709f}.study-button.active{border-color:var(--green);box-shadow:0 0 0 2px rgba(74,222,128,.13)}.study-button.done::after{content:'Concluído';display:block;color:var(--green);font-size:12px;font-weight:900}.study-button strong,.study-button small{display:block}.study-button small{color:var(--muted)}.workspace{min-width:0}.brief{display:grid;grid-template-columns:1fr auto;gap:20px;align-items:start;padding:22px;border:1px solid var(--line);border-radius:16px 16px 0 0;background:var(--paper);color:var(--ink)}.brief h2{margin:3px 0 5px;font-size:25px}.brief p{margin:0;color:#526078}.concept{display:inline-flex;padding:6px 10px;border-radius:999px;background:#dcfce7;color:#166534;font-size:13px;font-weight:900}.tip{margin-top:14px!important;padding-left:14px;border-left:3px solid #f59e0b}.editor-panel{border:1px solid var(--line);border-top:0;background:#091422}.editor-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;background:#101f33;color:var(--muted);font:13px Consolas,monospace}.editor{display:block;width:100%;min-height:420px;padding:22px;border:0;outline:0;resize:vertical;background:#091422;color:#d9fbe5;font:15px/1.65 Consolas,monospace;tab-size:4}.editor:focus{box-shadow:inset 0 0 0 3px var(--focus)}.editor-help{color:var(--muted)}.editor-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 16px;border-top:1px solid var(--line);background:var(--panel)}.button-group{display:flex;gap:8px;flex-wrap:wrap}.btn{min-height:46px;padding:10px 17px;border:1px solid transparent;border-radius:10px;font-weight:900}.btn:focus-visible,.study-button:focus-visible{outline:3px solid var(--focus);outline-offset:2px}.btn-primary{background:var(--green);color:#052e16}.btn-primary:hover{background:#86efac}.btn-primary:disabled{cursor:wait;opacity:.65}.btn-secondary{border-color:var(--line);background:transparent;color:var(--text)}.btn-secondary:hover{background:var(--panel-2)}.result{min-height:118px;padding:20px;border:1px solid var(--line);border-top:0;border-radius:0 0 16px 16px;background:var(--panel)}.result-empty{margin:0;color:var(--muted)}.result .result-card{margin:0;padding:0;border:0;background:transparent}.result .feedback{padding:16px;border-radius:12px}.result .feedback.ok{background:#092c20;color:#d1fae5;border:1px solid #166534}.result .feedback.bad{background:#35151a;color:#fee2e2;border:1px solid #7f1d1d}.result .output{min-height:70px;padding:14px;border-radius:10px;background:#050c16;color:#d9fbe5;white-space:pre-wrap;font:14px/1.6 Consolas,monospace}.status-line{min-height:24px;color:var(--muted);font-size:14px}.status-line.ok{color:var(--green)}.status-line.bad{color:var(--red)}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:900px){.lab-header{position:static}.lab-intro{grid-template-columns:1fr}.study-flow{justify-content:flex-start}.lab-grid{grid-template-columns:1fr}.study-list{position:static;display:flex;overflow:auto;max-height:none;padding:0 0 8px}.study-button{min-width:235px}.editor{min-height:360px}}@media(max-width:560px){.lab-main{width:min(100% - 24px,1320px);padding-top:24px}.lab-header{padding:14px 12px}.lab-nav a{padding:8px}.lab-intro h1{font-size:36px}.brief{grid-template-columns:1fr}.editor-actions{align-items:stretch;flex-direction:column}.button-group,.btn{width:100%}.button-group{display:grid;grid-template-columns:1fr 1fr}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
